"use client";

// ── THE GROVE'S MUSIC ────────────────────────────────────────────────────────────────────────────────────────
// Luke: "The grove needs music for each zone generated by us, we always generate our own music. The music
// should fit the theme of the level and zone."
//
// ⚠️ SYNTHESISED, LIKE EVERY OTHER SOUND IN THIS GAME. Eighty-four built zones — one hundred and forty-four
// designed — is eighty-four loops to write, host, cache-bust and 404 on a phone with one bar, on a screen that
// is already downloading a backdrop, a slab, a hero, a pet and thirty creatures. As synthesis it is this file,
// it costs nothing to download, and a new zone is a row in a table rather than a commission.
//
// ── ⚠️ AND THERE IS NO TUNE IN IT, ON PURPOSE ────────────────────────────────────────────────────────────────
// This is the one hard lesson the arena already paid for, and it is written in capitals at the bottom of
// arena-audio.js. There WAS a melody there — a filtered square playing a written line in Dorian — and Luke:
// "the arena music is trash, everything else you made sounds great. this one is exceptionally naf."
//
// Both halves of that sentence are the same observation. Every sound effect in this game is a TRANSIENT or a
// TEXTURE, and synthesis is superb at those. A square wave playing a TUNE is the one thing synthesis is
// uniquely bad at: there is no performance in it, every note is identical, and the ear has heard that exact
// timbre in a thousand free games. So the Grove gets a PLACE rather than a track: moving air, a drone, a slow
// pulse, and the things that live in that zone making their noises. Nothing here is trying to be hummable,
// and nothing here will be mistaken for a ringtone.
//
// ── WHAT MAKES A ZONE SOUND LIKE ITSELF: THREE INPUTS, THREE JOBS ────────────────────────────────────────────
// Exactly the split the art already uses — a map is a PLACE, a biome is the GROUND, depth is the CLIMB (see
// BIOME_NODE in grove-maps.js, which borrows a map symbol per biome for the same reason).
//
//   MAP    → THE HARMONY. A place is a key and a mode. Twelve maps, twelve modes, and because there is no
//            melody the mode lands structurally rather than decoratively: it picks the interval the DRONE is
//            built on. The Ashen Reach is Locrian, so its drone is a root and a FLAT fifth and the whole zone
//            sits slightly wrong; the Starfall Rim is whole-tone and never resolves anywhere. That is a real
//            mechanical difference, not a label.
//   BIOME  → THE VOICES. Ten biomes, ten texture kits. This is what makes two zones on the same map sound
//            different: a burrow is airless and scuttles, a char zone crackles and roars, a glow zone is moth
//            wings and inharmonic bells. One kit dresses many zones, same as one slab does.
//   DEPTH  → THE WEIGHT. `press`, 0 to 1 across the whole designed Grove. Thicket Edge has no drum at all —
//            "nothing here has noticed you yet" — and by the Ashen Reach there is a pulse, a sub-octave under
//            the drone and darker air. The climb is audible before anything attacks.
//
// Plus a MAP TINT: one voice per map laid over every zone of it, so a stone zone in the Frostmere cracks with
// ice and a stone zone in the Undercave echoes. Biome alone could not tell those apart, and the Frostmere
// sounding like a cave is the same continuity error as a hanging vine in the Rotwood.
//
// ── ⚠️ AND IT NEVER COMES ROUND ──────────────────────────────────────────────────────────────────────────────
// The arena's second rewrite learned that "nineteen seconds is still a loop" — tripling a phrase moves the
// moment you notice from the fifth pass to the tenth and does not remove it, because the phrase returns
// IDENTICAL. A grinder is in one Grove zone for an hour, which is twenty times longer than a bout, so a phrase
// that repeats at all is a phrase that will be heard repeating.
//
// So the harmony cycles (sixteen bars, ~a minute) and the CONTENT does not: every bar draws its textures,
// their count, their placement and their pitch jitter from a stream keyed on the bar number — same derivation
// `killRng` uses, for the same reason. Bar 9 and bar 25 share a chord and share nothing else. There is no
// repeat length to find.
//
// ── ON THE ARENA'S CONTEXT, THROUGH THE ARENA'S LIMITER ──────────────────────────────────────────────────────
// Own `subBus`, so stopping a bed cuts its tail no matter how far ahead it was scheduled — the bug Luke heard
// in the casino as "it's now playing two tracks over each other". The context, the compressor and the MUTE are
// the shared ones; a second mute that could disagree with the first is worse than no mute at all.
import {
    audioParts, killBus, noise, subBus, tone, unlock,
} from "@/components/arena/arena-audio.js";
import { rngFrom } from "@/lib/marketplace/grove-roll.js";

// ── TUNING ───────────────────────────────────────────────────────────────────────────────────────────────────
// Deliberately under the effects. A hit, a kill and a boss notice have to cut through this without ducking,
// and a bed you notice is a bed that is too loud.
const BED_GAIN = 0.72;
const FADE_IN = 2.4;          // a zone fades up over its first bar, so arriving is not a sound starting
const FADE_OUT = 1.1;
const LOOKAHEAD = 0.45;       // how far ahead of the audio clock bars are built
const TICK_MS = 100;          // the timer only decides WHEN to schedule; the audio clock decides when it sounds

// ⚠️ THE DESIGNED TOTAL, NOT THE BUILT ONE. 144 is twelve maps of twelve — groveDepth's own note puts map 12
// zone 1 at depth 133, so the last zone of the Grove is 144. Anchoring on GROVE_ZONES.length instead would
// re-tune every existing zone the day a map ships: the Thicket would get heavier because somewhere new opened,
// which is the same mistake as sizing a difficulty span against built content (see GROVE_SCALE).
const DEEPEST = 144;

// ── THE TWELVE PLACES ────────────────────────────────────────────────────────────────────────────────────────
// `root`   the drone's fundamental, in Hz. Deeper maps sit lower: low end is most of what makes air feel heavy.
// `drone`  semitones to the drone's companion interval. 7 is a fifth (stable), 5 a fourth (unresolved), 6 a
//          flat fifth (sour). THIS IS WHERE THE MODE ACTUALLY LANDS, because there is no melody to carry it.
// `walk`   eight steps of root movement in semitones, two bars each, all inside the mode. Slow, and returning
//          to zero often — it is a drone with a current in it, not a progression.
// `sour`   the interval added as a THIRD drone voice while a boss is awake. The mode's most unstable note, so
//          the zone turns dissonant without transposing — a boss should be heard arriving in the harmony.
// `beat`   seconds per beat; a bar is four. Slow at the top of the game, tighter as it gets worse.
// `lift`   where the drone's lowpass sits. High for thin, bright, high-altitude places; low for buried ones.
// `tint`   the voice this map lays over every one of its zones, whatever the ground is.
//
// ⚠️ ALL TWELVE ARE DECLARED, THOUGH ONLY SEVEN ARE BUILT. Same rule as the recipe ladders and the zone
// tables: the design is decided before the art lands, and raising MAPS_BUILT must not need a second edit in a
// file nobody remembers. A map with no backdrop is unreachable, not silent.
const MAP_VOICE = {
    // A living forest, and the friendliest thing in the game. Dorian — one note from natural minor, the sixth
    // natural, so it is minor enough to have something in it and bright enough not to be a funeral.
    1: { name: "The Grove", mode: "A Dorian", root: 110.00, drone: 7, sour: 1, beat: 1.05, lift: 560, tint: "bird",
        walk: [0, 0, 5, 0, 0, -3, 5, 0] },
    // Underground. Aeolian, a full octave lower than the forest above it, and the lowpass almost shut: no sky,
    // no distance, nothing to carry a high frequency anywhere.
    2: { name: "The Undercave", mode: "C Aeolian", root: 65.41, drone: 7, sour: 1, beat: 0.95, lift: 320, tint: "echoKnock",
        walk: [0, 0, 0, -4, 0, 0, 3, 0] },
    // Phrygian. The flat second is the whole sound of this map — it never settles, which is correct for
    // standing in water that is deeper than the pole you brought.
    3: { name: "The Sunken Fen", mode: "D Phrygian", root: 73.42, drone: 5, sour: 1, beat: 1.10, lift: 420, tint: "bubble",
        walk: [0, 1, 0, 0, 0, -4, 1, 0] },
    // Mixolydian — major with a flat seventh. Open, weathered, and the ancestor of every song ever sung on a
    // boat, without being one.
    4: { name: "The Saltwrack Coast", mode: "G Mixolydian", root: 98.00, drone: 7, sour: 6, beat: 0.86, lift: 700, tint: "surf",
        walk: [0, 0, -2, 0, 5, 0, -2, 0] },
    // Harmonic minor: a MAJOR dominant over a minor tonic. Ceremonial and slightly wrong, which is a drowned
    // city with the sigils still facing inward.
    5: { name: "The Drowned Ruins", mode: "E harmonic minor", root: 82.41, drone: 7, sour: 6, beat: 0.98, lift: 480, tint: "toll" ,
        walk: [0, 0, 7, 7, 0, 8, 7, 0] },
    // Phrygian dominant — flat second, major third. The desert mode, and the only one here that sounds hot.
    6: { name: "The Gilded Waste", mode: "F Phrygian dominant", root: 87.31, drone: 7, sour: 1, beat: 0.90, lift: 760, tint: "shimmer",
        walk: [0, 1, 0, 0, 5, 1, 0, 0] },
    // ⚠️ LOCRIAN, WHICH MEANS THE DRONE ITSELF IS A FLAT FIFTH. Every other map's drone is a root and a
    // consonance; this one's is a tritone, and it is the single most audible thing about arriving here. A
    // forest that burned standing up and never fell should not sound resolved.
    7: { name: "The Ashen Reach", mode: "B-flat Locrian", root: 58.27, drone: 6, sour: 1, beat: 0.78, lift: 380, tint: "ashfall",
        walk: [0, 0, 6, 0, 1, 0, 6, 0] },
    8: { name: "The Thunder Steppe", mode: "D Aeolian", root: 73.42, drone: 7, sour: 6, beat: 0.82, lift: 620, tint: "thunder",
        walk: [0, 0, -5, 0, 3, 0, 5, 0] },
    // Thin and glassy. The root is high for a drone on purpose — cold air carries the top end and nothing else.
    9: { name: "The Frostmere", mode: "G-sharp Aeolian", root: 103.83, drone: 7, sour: 1, beat: 1.00, lift: 820, tint: "icecrack",
        walk: [0, 0, 3, 0, 0, -4, 0, 0] },
    // Lydian. The sharp fourth against a root drone is vertigo, which is what a mile of air underneath you is.
    10: { name: "The Glass Peaks", mode: "E Lydian", root: 82.41, drone: 7, sour: 6, beat: 0.88, lift: 900, tint: "howl",
        walk: [0, 0, 6, 0, 7, 0, 2, 0] },
    // Dorian again, like the Grove, and a fourth-drone instead of a fifth — the same forest, overgrown and
    // cloying. Deliberately the one echo of map one in the set: the Rotgarden is a garden that ate its wall.
    11: { name: "The Rotgarden", mode: "C Dorian", root: 65.41, drone: 5, sour: 1, beat: 0.94, lift: 500, tint: "spore",
        walk: [0, 0, 5, 0, 3, 5, 0, 0] },
    // ⚠️ NO KEY AT ALL. Whole-tone: six equal steps, no tonic, nothing that can resolve because every
    // interval is the same interval. The edge of the world is the one place that should not sound like music.
    12: { name: "The Starfall Rim", mode: "A whole-tone", root: 55.00, drone: 6, sour: 6, beat: 1.25, lift: 640, tint: "farlight",
        walk: [0, 2, 4, 6, 8, 10, 6, 2] },
};

// ── ⚠️ AND A ZONE GETS ITS OWN KEY ───────────────────────────────────────────────────────────────────────────
// Twelve semitone shifts, one per position within a map, applied to the root.
//
// WHY THIS EXISTS. Map one has THREE `wood` zones — Thicket Edge, the Fernway, the Old Stand — and
// GROVE_BIOMES says, correctly, that they are the same forest floor at different depths, so they draw the
// same kit and the same air. Depth separates them a little (the Thicket has no pulse and Heartwood does), but
// across one map that difference is small, and map one is where a player spends the most hours of their life.
// Three zones that sound interchangeable on the map everybody plays is the one thing this design could get
// badly wrong.
//
// A key change fixes it for nothing. The mode, the drone interval, the walk SHAPE and the tint all survive
// transposition untouched — so the Fernway is unmistakably the same place as the Thicket and is just as
// unmistakably not the same zone.
//
// ⚠️ ALL TWELVE ARE DIFFERENT, AND THE FIRST VERSION'S WEREN'T. It reused three shifts on the theory that
// they should be consonant with each other — which is wrong, because two zones are never heard at once and
// there is no interval between them to be consonant. The only real constraint is REGISTER: a shift of a
// minor seventh down off the Ashen Reach's 58Hz root lands at 34Hz, which is mush through a phone. So the
// range is held inside a fifth either way, and nine repeated shifts across seven maps — Basker's Rock and
// Slinger's Pass, the Boar Run and the Slag Run, Ram Ledge and Silk Crevasse — stopped being interchangeable.
//
// ⚠️ BY POSITION, NOT BY SEED. Walking zone 1 → 2 → 3 should be a progression rather than a scatter, and a
// hashed shift would put neighbours a random distance apart; this way the map drifts and comes back, which
// is a shape rather than noise.
const ZONE_SHIFT = [0, -2, 3, -5, 5, -3, 2, -7, 7, -4, 4, 1];

// ── THE TEN GROUNDS ──────────────────────────────────────────────────────────────────────────────────────────
// `air` is the room tone: one long filtered-noise swell a bar, and the single biggest cue for what kind of
// space you are standing in. `kit` is what lives there. `per` is how many of those a bar gets, drawn from the
// bar's own stream — a range, so density itself varies and nothing settles into a rhythm.
//
// ⚠️ ONLY WHAT BELONGS THERE, same rule and same reason as GROVE_BIOMES' growth lists. A water drip in the
// Stubble Field is not a texture, it is a continuity error — and ember crackle in a living wood is the
// audio version of a flowering creeper in a burnt forest.
const BIOME_VOICE = {
    // Living wood. Leaves, a branch somewhere, and the hiss of a canopy moving.
    wood: { air: { type: "bandpass", from: 520, to: 1500, q: 0.8, gain: 0.034 },
        kit: ["gust", "gust", "knock", "whisper"], per: [2, 4] },
    // Wet and close. The lowpass CLOSES across the bar rather than opening — damp air swallows the top end.
    moss: { air: { type: "lowpass", from: 760, to: 420, q: 0.7, gain: 0.040 },
        kit: ["drip", "drip", "whisper", "gust"], per: [2, 4] },
    // Dry canes. Nothing here is soft, so nothing here has a tail.
    bramble: { air: { type: "bandpass", from: 900, to: 2200, q: 1.2, gain: 0.030 },
        kit: ["rattle", "rattle", "scuttle", "whisper"], per: [2, 5] },
    // Cut stubble to the horizon. The widest air in the game and the emptiest kit: open ground is mostly wind.
    field: { air: { type: "bandpass", from: 380, to: 1200, q: 0.5, gain: 0.052 },
        kit: ["gust", "gust", "gust", "rattle"], per: [2, 3] },
    // Hollow. Long tails, far-off falls, and the knocks come back at you.
    stone: { air: { type: "lowpass", from: 300, to: 520, q: 0.9, gain: 0.038 },
        kit: ["drip", "rumble", "knock"], per: [1, 3] },
    // Underground, and the one biome with no moving air at all — the swell is almost sub-audible, which is
    // what makes a burrow feel like it has a ceiling six inches above your head.
    burrow: { air: { type: "lowpass", from: 190, to: 300, q: 1.0, gain: 0.046 },
        kit: ["scuttle", "scuttle", "rumble", "drip"], per: [2, 4] },
    // ⚠️ THE ONE THAT PROVES THE TABLE IS DOING SOMETHING, exactly as char does in GROVE_BIOMES. No drip, no
    // leaf, no scuttle — nothing alive. Fire, ember and the ash it is all standing in.
    char: { air: { type: "highpass", from: 1800, to: 3200, q: 0.6, gain: 0.030 },
        kit: ["crackle", "crackle", "roar", "rumble"], per: [2, 4] },
    // Worked timber under load. A high-Q band around the body of a plank, and things straining in it.
    plank: { air: { type: "bandpass", from: 600, to: 1100, q: 1.6, gain: 0.032 },
        kit: ["creak", "knock", "rattle"], per: [2, 4] },
    // Lit from the air. The glow IS the zone, so the texture is wings and inharmonic partials, and the air is
    // nothing but top end.
    glow: { air: { type: "highpass", from: 2600, to: 5200, q: 0.6, gain: 0.024 },
        kit: ["flutter", "flutter", "bell", "whisper"], per: [2, 4] },
    // The oldest thing in the forest and the most overgrown: the densest kit, and something enormous leaning.
    heart: { air: { type: "lowpass", from: 420, to: 900, q: 0.8, gain: 0.044 },
        kit: ["groan", "gust", "whisper", "knock", "whisper"], per: [3, 5] },
};

// ── RAW VOICES ───────────────────────────────────────────────────────────────────────────────────────────────
// `tone` and `noise` are the shared transient helpers and they are used heavily below — but both have a
// sub-20ms attack, which is a struck thing. A drone and a swell have to ARRIVE, over the better part of a
// second, and that lateness is the whole difference between moving air and a burst of hiss. So these two
// build their own nodes on the arena's context (see `audioParts`) and hang them on this bed's own bus.
//
// `at` is seconds from now, clamped at zero: a bar is scheduled against the audio clock, and a timer that
// fired late must never ask for a note in the past.
function pad({ at = 0, freq = 110, dur = 3, gain = 0.05, type = "sawtooth", detune = 0, cut = 520, open = 2.2, q = 0.8, bus = null }) {
    const p = audioParts();
    if (!p || !bus) return;
    const { ctx } = p;
    const t = ctx.currentTime + Math.max(0, at);
    try {
        const o = ctx.createOscillator();
        const f = ctx.createBiquadFilter();
        const g = ctx.createGain();
        o.type = type;
        o.frequency.value = freq;
        o.detune.value = detune;
        f.type = "lowpass";
        f.Q.value = q;
        // The filter breathes across the note. A fixed cutoff on a held saw is a synth pad; a moving one is
        // something being bowed.
        f.frequency.setValueAtTime(cut, t);
        f.frequency.linearRampToValueAtTime(cut * open, t + dur * 0.45);
        f.frequency.linearRampToValueAtTime(cut, t + dur);
        g.gain.setValueAtTime(0.0001, t);
        g.gain.linearRampToValueAtTime(gain, t + dur * 0.38);
        g.gain.setValueAtTime(gain, t + dur * 0.62);
        g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
        o.connect(f); f.connect(g); g.connect(bus);
        o.start(t); o.stop(t + dur + 0.04);
    } catch { /* a missing drone must never break the zone */ }
}

function breath({ at = 0, dur = 2, gain = 0.03, type = "bandpass", from = 600, to = 600, q = 1, bus = null }) {
    const p = audioParts();
    if (!p || !p.noiseBuf || !bus) return;
    const { ctx, noiseBuf } = p;
    const t = ctx.currentTime + Math.max(0, at);
    try {
        const s = ctx.createBufferSource();
        s.buffer = noiseBuf; s.loop = true;
        const f = ctx.createBiquadFilter();
        f.type = type; f.Q.value = q;
        f.frequency.setValueAtTime(from, t);
        if (to !== from) f.frequency.exponentialRampToValueAtTime(Math.max(40, to), t + dur * 0.72);
        const g = ctx.createGain();
        g.gain.setValueAtTime(0.0001, t);
        g.gain.linearRampToValueAtTime(gain, t + dur * 0.42);
        g.gain.linearRampToValueAtTime(gain * 0.8, t + dur * 0.66);
        g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
        s.connect(f); f.connect(g); g.connect(bus);
        s.start(t); s.stop(t + dur + 0.05);
    } catch { /* ditto */ }
}

// ── THE THINGS A ZONE IS MADE OF ─────────────────────────────────────────────────────────────────────────────
// Every one takes the bar's own random stream, so the same voice is never heard twice identically: the pitch,
// the length, the count and the spacing all move. That is the difference between a texture and a sample.
//
// ⚠️ GAINS ARE TINY AND THAT IS NOT A MISTAKE. There are two to five of these a bar on top of a drone, an air
// swell and a drum, all through one compressor. A texture at 0.02 is clearly audible in a quiet forest and
// invisible under a fight, which is exactly the behaviour wanted from scenery.
const VOICE = {
    /** Moving air with a direction: the filter opens upward, so it reads as a gust passing rather than hiss. */
    gust(at, bus, r) {
        breath({ at, dur: 1.5 + r() * 1.3, gain: 0.030 + r() * 0.020, type: "bandpass",
            from: 460 + r() * 220, to: 1300 + r() * 900, q: 0.8, bus });
    },
    /** Growth close to the ear. All top end, no body — leaves and fronds rather than wind. */
    whisper(at, bus, r) {
        breath({ at, dur: 1.1 + r() * 0.9, gain: 0.014 + r() * 0.012, type: "highpass",
            from: 1700, to: 3200 + r() * 900, q: 0.6, bus });
    },
    /** Water finding the floor. A steep pitch drop is the drop; the quiet low tone after it is the pool. */
    drip(at, bus, r) {
        const top = 980 + r() * 700;
        tone({ at, freq: top, to: top * 0.28, type: "sine", dur: 0.085, gain: 0.05, bus });
        tone({ at: at + 0.02, freq: top * 0.3, type: "sine", dur: 0.42, gain: 0.011, bus });
    },
    /** Wood struck once. The steep fall IS what makes it read as wood rather than as a note. */
    knock(at, bus, r) {
        const f0 = 200 + r() * 90;
        tone({ at, freq: f0, to: f0 * 0.34, type: "sine", dur: 0.09, gain: 0.062, bus });
        noise({ at, dur: 0.05, gain: 0.026, type: "lowpass", freq: 900, sweepTo: 260, bus });
    },
    /** The Undercave's tint: the same knock, twice more, quieter and further away. A hall with a far wall. */
    echoKnock(at, bus, r) {
        VOICE.knock(at, bus, r);
        const gap = 0.34 + r() * 0.2;
        const f0 = 180 + r() * 70;
        tone({ at: at + gap, freq: f0, to: f0 * 0.34, type: "sine", dur: 0.10, gain: 0.020, bus });
        tone({ at: at + gap * 2, freq: f0 * 0.9, to: f0 * 0.30, type: "sine", dur: 0.11, gain: 0.008, bus });
    },
    /** Dry canes against each other. Uneven gaps — anything evenly spaced reads as a drum roll. */
    rattle(at, bus, r) {
        const n = 4 + Math.floor(r() * 4);
        let o = 0;
        for (let i = 0; i < n; i += 1) {
            o += 0.03 + r() * 0.05;
            noise({ at: at + o, dur: 0.022, gain: 0.018 + r() * 0.012, type: "highpass", freq: 2200 + r() * 2000, bus });
        }
    },
    /** Small legs, and they ACCELERATE. Something that notices it has been noticed. */
    scuttle(at, bus, r) {
        const n = 6 + Math.floor(r() * 5);
        let o = 0;
        for (let i = 0; i < n; i += 1) {
            o += 0.055 - (i / n) * 0.03 + r() * 0.012;
            noise({ at: at + o, dur: 0.018, gain: 0.013, type: "bandpass", freq: 1500 + r() * 1400, q: 2.4, bus });
        }
    },
    /** Something large settling a long way off, with a few pieces of it arriving separately. */
    rumble(at, bus, r, press) {
        breath({ at, dur: 2.0 + r() * 1.2, gain: 0.046 + press * 0.045, type: "lowpass", from: 80, to: 190, q: 1.2, bus });
        const n = 1 + Math.floor(r() * 3);
        for (let i = 0; i < n; i += 1) VOICE.knock(at + 0.3 + r() * 1.2, bus, r);
    },
    /** Embers. A dozen-odd micro pops scattered across the bar — sparse, random, and never a pattern. */
    crackle(at, bus, r) {
        const n = 8 + Math.floor(r() * 9);
        for (let i = 0; i < n; i += 1) {
            noise({ at: at + r() * 1.6, dur: 0.012, gain: 0.013 + r() * 0.013,
                type: "highpass", freq: 2800 + r() * 3400, bus });
        }
    },
    /** Fire with a size to it. Low, wide, and it does not stop. */
    roar(at, bus, r, press) {
        breath({ at, dur: 2.4 + r() * 1.2, gain: 0.055 + press * 0.040, type: "lowpass", from: 110, to: 180, q: 0.9, bus });
    },
    /** Timber under load. A slow upward bend on a reedy voice: the one sound here that is genuinely a note. */
    creak(at, bus, r) {
        const f0 = 84 + r() * 40;
        tone({ at, freq: f0, to: f0 * (1.4 + r() * 0.5), type: "sawtooth", dur: 0.9 + r() * 0.6, gain: 0.019, bus });
        noise({ at: at + 0.05, dur: 0.5, gain: 0.009, type: "bandpass", freq: 1400, q: 3, bus });
    },
    /** Moth wings: a burst train around 17Hz, swelling in and out. Amplitude modulation, by hand. */
    flutter(at, bus, r) {
        const n = 8 + Math.floor(r() * 7);
        const rate = 0.055 + r() * 0.02;
        for (let i = 0; i < n; i += 1) {
            noise({ at: at + i * rate, dur: 0.03, gain: 0.015 * (1 - Math.abs(i / n - 0.5)),
                type: "bandpass", freq: 800 + r() * 500, q: 1.6, bus });
        }
    },
    /**
     * Lit glass. Two partials at 1 : 1.53 — INHARMONIC, deliberately, which is the difference between a bell
     * and the chime that opens a dialog box. The arena's anvil is built the same way for the same reason.
     */
    bell(at, bus, r) {
        const f0 = 1180 + r() * 620;
        tone({ at, freq: f0, type: "square", dur: 0.8 + r() * 0.5, gain: 0.010, bus });
        tone({ at, freq: f0 * 1.53, type: "square", dur: 0.5, gain: 0.006, bus });
        noise({ at, dur: 0.02, gain: 0.011, type: "highpass", freq: 4200, bus });
    },
    /** Something enormous leaning. Two drones a hair apart, so they beat against each other. */
    groan(at, bus, r) {
        const f0 = 54 + r() * 14;
        pad({ at, freq: f0, dur: 2.4 + r() * 1.0, gain: 0.042, cut: 180, open: 1.7, bus });
        pad({ at: at + 0.2, freq: f0 * 1.03, dur: 2.0, gain: 0.028, cut: 200, open: 1.5, bus });
    },
    /** Fen gas. Pitch RISING is the entire trick — a falling blip is a drip, a climbing one is a bubble. */
    bubble(at, bus, r) {
        const n = 3 + Math.floor(r() * 4);
        for (let i = 0; i < n; i += 1) {
            const f0 = 150 + r() * 120;
            tone({ at: at + i * (0.1 + r() * 0.2), freq: f0, to: f0 * (2.4 + r()), type: "sine", dur: 0.075, gain: 0.028, bus });
        }
    },
    /** A breaker arriving and then going out again. The recede is a second swell running backwards. */
    surf(at, bus, r) {
        const dur = 2.2 + r() * 1.2;
        breath({ at, dur, gain: 0.070, type: "lowpass", from: 260, to: 900, q: 0.7, bus });
        breath({ at: at + dur * 0.55, dur: dur * 0.9, gain: 0.040, type: "lowpass", from: 820, to: 220, q: 0.7, bus });
    },
    /** A bell in a flooded hall, struck once, a long way down. Rare by construction — see `tintEvery`. */
    toll(at, bus, r) {
        const f0 = 96 + r() * 20;
        tone({ at, freq: f0, type: "triangle", dur: 2.6, gain: 0.032, bus });
        tone({ at, freq: f0 * 2.76, type: "triangle", dur: 1.5, gain: 0.013, bus });
        tone({ at, freq: f0 * 5.40, type: "sine", dur: 0.9, gain: 0.006, bus });
        noise({ at, dur: 0.04, gain: 0.016, type: "bandpass", freq: 1800, q: 1.2, bus });
    },
    /** Heat off flat ground: a narrow band pulsing, which is what a mirage sounds like if it sounds like anything. */
    shimmer(at, bus, r) {
        for (let i = 0; i < 6; i += 1) {
            breath({ at: at + i * 0.34, dur: 0.4, gain: 0.013, type: "bandpass",
                from: 2500 + r() * 900, to: 3200, q: 5, bus });
        }
    },
    /** "Ash falling like weather." A high hiss settling downward over three seconds, and never clearing. */
    ashfall(at, bus, r) {
        breath({ at, dur: 2.6 + r() * 1.0, gain: 0.028, type: "highpass", from: 2600, to: 1500, q: 0.6, bus });
    },
    /** A storm that has parked. Mostly sub, with a crack arriving late and only sometimes. */
    thunder(at, bus, r) {
        breath({ at, dur: 2.8 + r() * 1.4, gain: 0.080, type: "lowpass", from: 56, to: 130, q: 1.4, bus });
        if (r() < 0.4) noise({ at: at + 0.4 + r() * 0.8, dur: 0.35, gain: 0.020, type: "highpass", freq: 1800, sweepTo: 700, bus });
    },
    /** Ice deciding. A hard tick, then the fracture running away from it for a second. */
    icecrack(at, bus, r) {
        const f0 = 2200 + r() * 1200;
        tone({ at, freq: f0, to: f0 * 0.7, type: "square", dur: 0.035, gain: 0.020, bus });
        noise({ at, dur: 0.03, gain: 0.018, type: "highpass", freq: 5200, bus });
        breath({ at: at + 0.03, dur: 1.1, gain: 0.011, type: "bandpass", from: 3000, to: 1400, q: 4, bus });
    },
    /** Wind in a gap it does not fit through. High Q is the whole voice — that is what makes it a note. */
    howl(at, bus, r) {
        breath({ at, dur: 2.4 + r() * 1.3, gain: 0.038, type: "bandpass",
            from: 620 + r() * 300, to: 1900 + r() * 700, q: 6, bus });
    },
    /** A puff of something you should not breathe. Falls in pitch as it spreads. */
    spore(at, bus, r) {
        noise({ at, dur: 0.45, gain: 0.024, type: "bandpass", freq: 1300, sweepTo: 560, q: 1.1, bus });
        if (r() < 0.5) noise({ at: at + 0.3, dur: 0.6, gain: 0.013, type: "bandpass", freq: 900, sweepTo: 420, q: 1.1, bus });
    },
    /** "Light arriving from somewhere that is no longer there." A pure sine, far away, going nowhere. */
    farlight(at, bus, r) {
        pad({ at, freq: 740 + r() * 300, dur: 2.8, gain: 0.013, type: "sine", cut: 1600, open: 1.2, bus });
    },
    /**
     * Something small and alive, twice.
     *
     * ⚠️ FILTERED NOISE, NOT TWO TONES. Two short pitched blips is a notification; a high-Q band sweeping
     * across a breath of noise is a throat. Same rule as the hit sounds in grove-sfx.js — a pure oscillator
     * reads as UI, and the Grove's first map is the one place that must not.
     */
    bird(at, bus, r) {
        const f0 = 2500 + r() * 900;
        noise({ at, dur: 0.055, gain: 0.019, type: "bandpass", freq: f0, sweepTo: f0 * 1.35, q: 9, bus });
        noise({ at: at + 0.11, dur: 0.05, gain: 0.015, type: "bandpass", freq: f0 * 1.2, sweepTo: f0 * 0.9, q: 9, bus });
    },
};

// ── THE SPEC ─────────────────────────────────────────────────────────────────────────────────────────────────
/** A stable 32-bit hash of the zone id, so a zone's stream is ITS stream for ever rather than per session. */
function hashId(id) {
    let h = 2166136261;
    const s = String(id || "");
    for (let i = 0; i < s.length; i += 1) {
        h ^= s.charCodeAt(i);
        h = Math.imul(h, 16777619);
    }
    return h >>> 0;
}

/**
 * Everything the scheduler needs for one zone, resolved from the three tables.
 *
 * Exported because the lab displays it — auditioning eighty-four zones means reading what each one IS, not
 * just hearing it, and a bench that cannot say "Dorian, moss, depth 2" cannot be used to judge whether the
 * theme landed. See /marketplace/grove/music.
 */
export function groveTrack(zone) {
    if (!zone?.id) return null;
    const mapN = Math.max(1, Math.min(12, Number(zone.map) || 1));
    const m = MAP_VOICE[mapN] || MAP_VOICE[1];
    const biome = BIOME_VOICE[zone.biome] ? zone.biome : "wood";
    const b = BIOME_VOICE[biome];

    // ── ⚠️ zone.n IS ALREADY GLOBAL DEPTH, SO IT IS NOT PUT THROUGH groveDepth ───────────────────────
    // MAP_ZONES sets `n: depth` (grove-maps.js) and map one's twelve happen to equal their depth, which is
    // why `zone.n` is what grove.js indexes GROVE_ZONES with and what it compares against `unlocked_n`.
    // Calling groveDepth(zone.map, zone.n) on top of that would add the map offset a SECOND time — map 7
    // zone 1 would come out at 145 rather than 73, and the first zone of a map would be heavier than the
    // last zone of the one after it. (GroveScene's spawner does exactly that today; flagged to Luke.)
    const depth = Math.max(1, Number(zone.n) || 1);
    // Compressed so the built half of the game uses more than the bottom half of the range: depth 84 — the
    // deepest zone that exists — lands near 0.7 rather than 0.58, and the Thicket still sits at almost nothing.
    const press = Math.pow(Math.min(1, depth / DEEPEST), 0.7);
    const seed = hashId(zone.id);
    // Where in its own map this zone sits — the thing `zone.n` stopped being the moment it became global
    // depth. Twelve zones a map, so this is the only arithmetic needed to get it back.
    const spot = (depth - 1) % 12;
    const shift = ZONE_SHIFT[spot];

    return {
        key: String(zone.id),
        zoneName: zone.name || zone.id,
        mapN,
        mapName: m.name,
        mode: m.mode,
        biome,
        depth,
        press,
        seed,
        spot,
        shift,
        // ⚠️ THE MAP'S ROOT, MOVED TO THIS ZONE'S KEY. Everything that carries the map's identity — the mode,
        // the drone interval, the walk, the tint — is relative to this and so travels with it unchanged.
        root: m.root * Math.pow(2, shift / 12),
        drone: m.drone,
        sour: m.sour,
        walk: m.walk,
        beat: m.beat,
        barSec: m.beat * 4,
        lift: m.lift,
        tint: m.tint,
        // Rarer the louder it is. A toll in a flooded hall every twelve bars is an event; every two bars is
        // a clock, and a clock is the thing a player hears repeating.
        tintEvery: m.tint === "toll" || m.tint === "thunder" ? 8 : m.tint === "surf" ? 2 : 4,
        // ⚠️ OFFSET BY THE ZONE'S OWN SEED. Without this every zone of a map tints on the same bar, so two
        // zones of the Saltwrack would break identically — the map's voice would read as the map's metronome.
        tintPhase: seed % (m.tint === "toll" || m.tint === "thunder" ? 8 : m.tint === "surf" ? 2 : 4),
        // Depth darkens the room. Deeper air carries less top end, which is most of why a deep place feels
        // like it is pressing on you, and it costs one multiplication rather than a second table.
        air: {
            ...b.air,
            from: b.air.from * (1 - 0.26 * press),
            to: b.air.to * (1 - 0.26 * press),
            gain: b.air.gain * (0.9 + 0.35 * press),
        },
        kit: b.kit,
        per: b.per,
    };
}

// ── THE SCHEDULER ────────────────────────────────────────────────────────────────────────────────────────────
let bed = null;        // what is actually sounding: { spec, bus, bar, nextAt, timer }
let wanted = null;     // the zone the scene says we should be in; survives a tab going hidden
let danger = 0;        // 0 comfortable, 1 about to die
let bossOn = false;
let listening = false; // the visibility/gesture listeners, attached once

function scheduleBar(b, bar, t) {
    const p = audioParts();
    if (!p || !b.bus) return;
    const { ctx } = p;
    const s = b.spec;
    const bus = b.bus;
    const at0 = Math.max(0, t - ctx.currentTime);
    const { beat, barSec, press } = s;

    // ⚠️ ONE STREAM PER BAR, DERIVED — NOT ONE RUNNING STREAM. Same shape and same reason as `killRng`: the
    // bar number is the key, so bar 400 is reproducible without replaying 399 bars, and the lab can jump
    // straight to a bar to hear what it does.
    const r = rngFrom((s.seed ^ Math.imul(bar + 1, 0x9E3779B1)) >>> 0);

    // How loud it is ALLOWED to get. A boss awake is worth the same as being two thirds dead: both mean the
    // next thirty seconds matter.
    const heat = Math.max(danger, bossOn ? 0.55 : 0);

    // ── THE HARMONY ── two bars a step, so a walk of eight is a sixteen-bar cycle: around a minute, slow
    // enough that the step changing is felt rather than noticed.
    const semis = s.walk[Math.floor(bar / 2) % s.walk.length];
    const rootHz = s.root * Math.pow(2, semis / 12);

    // ── THE DRONE ── the spine, and it never stops. Two voices detuned against each other at the root plus
    // the mode's companion interval, held 1.3 bars so consecutive bars OVERLAP. A drone that lands exactly
    // on the bar line pumps, and a pumping drone is a pad being retriggered.
    const droneDur = barSec * 1.3;
    const g0 = 0.052 + press * 0.028;
    pad({ at: at0, freq: rootHz, dur: droneDur, gain: g0, detune: -6, cut: s.lift, open: 2.4, bus });
    pad({ at: at0, freq: rootHz, dur: droneDur, gain: g0 * 0.8, detune: 7, cut: s.lift, open: 2.4, bus });
    pad({ at: at0, freq: rootHz * Math.pow(2, s.drone / 12), dur: droneDur, gain: g0 * 0.5,
        cut: s.lift * 1.1, open: 2.0, bus });
    // The sub. Arrives about a fifth of the way down the Grove and is most of what makes the deep maps feel
    // heavy — low end is the one axis a phone speaker reads as SIZE rather than as volume.
    //
    // ⚠️ AND IT HAS A FLOOR. The Ashen Reach's root is 58Hz, a zone shift takes it to 39, and an octave under
    // THAT is 19Hz — which no phone speaker reproduces and most headphones barely do. It would have been a
    // node a bar, every bar, for the deepest half of the game, producing nothing audible while still taking
    // headroom off the limiter. Below the floor the layer stops being an octave and becomes a second voice on
    // the root with a different timbre, which is what it was there to do anyway.
    if (press > 0.22) {
        pad({ at: at0, freq: Math.max(34, rootHz / 2), dur: droneDur, gain: 0.030 + press * 0.030,
            type: "triangle", cut: 240, open: 1.6, bus });
    }
    // ⚠️ AND A BOSS IS HEARD IN THE HARMONY, NOT JUST IN THE DRUMS. A third voice at the mode's most
    // unstable interval — a flat second or a tritone against the root — so the zone turns dissonant while
    // something is hunting you and resolves again when it is dead. Transposing instead would just move the
    // track; this makes it WRONG, which is the point.
    if (bossOn) {
        pad({ at: at0, freq: rootHz * Math.pow(2, s.sour / 12), dur: droneDur * 0.8, gain: 0.028,
            cut: s.lift * 0.8, open: 1.8, bus });
    }

    // ── THE AIR ── the room, one swell a bar, wider into every fourth. Always on, at every depth: the zone
    // is a place before anything happens in it, which is the lesson the arena's crowd layer encodes.
    const wide = bar % 4 === 3;
    breath({
        at: at0, dur: barSec * (wide ? 1.15 : 0.9),
        gain: s.air.gain * (wide ? 1.45 : 1) * (0.85 + heat * 0.45),
        type: s.air.type, from: s.air.from, to: wide ? s.air.to * 1.25 : s.air.to, q: s.air.q, bus,
    });

    // ── THE PULSE ── and the first zones of the game do not have one.
    // "Nothing here has noticed you yet" is the Thicket's own blurb, and a drum under it would be telling
    // the player the opposite. It arrives around depth five, doubles at the Fen, and by the Ashen Reach there
    // is a kick, an off-beat and a tick layer. The climb is audible before a single thing attacks.
    const kick = (atk, gain) => {
        tone({ at: atk, freq: 58, to: 32, type: "sine", dur: 0.38, gain, bus });
        noise({ at: atk, dur: 0.055, gain: gain * 0.35, type: "lowpass", freq: 320, bus });
    };
    if (press > 0.08 || heat > 0.30) kick(at0, 0.120 + press * 0.110 + heat * 0.045);
    if (press > 0.30 || heat > 0.55) kick(at0 + beat * 2, 0.085 + press * 0.085);
    if (press > 0.50 || heat > 0.80) kick(at0 + beat * 3.5, 0.055 + press * 0.045);
    // The tick. The last layer to arrive and the only fast one — on alternate off-beats at first, then every
    // one when it is nearly over, so the bed accelerates while the tempo does not move at all.
    if (press > 0.45 || heat > 0.60) {
        for (let i = 0; i < 4; i += 1) {
            if (i % 2 === 1 || heat > 0.70) {
                noise({ at: at0 + beat * (i + 0.5), dur: 0.035, gain: 0.016 + heat * 0.012,
                    type: "highpass", freq: 5200, bus });
            }
        }
    }

    // ── WHAT LIVES HERE ── the identity layer, and the reason two zones of one map are told apart with your
    // eyes shut. Count, choice and placement all out of this bar's stream.
    const n = s.per[0] + Math.floor(r() * (s.per[1] - s.per[0] + 1));
    for (let i = 0; i < n; i += 1) {
        const v = VOICE[s.kit[Math.floor(r() * s.kit.length)]];
        if (v) v(at0 + r() * barSec * 0.92, bus, r, press);
    }

    // ── AND WHICH PLACE IT IS ── the map's own voice over the top, whatever the ground happens to be.
    if (bar % s.tintEvery === s.tintPhase) {
        const v = VOICE[s.tint];
        if (v) v(at0 + r() * barSec * 0.6, bus, r, press);
    }

    // ── THE THREAT ── a pair of notes FALLING, every other bar, while a boss is up.
    // ⚠️ DESCENDING, AND THAT IS THE WHOLE TRICK — it is the same grammar playBossNotice uses and for the
    // same documented reason: every reward sound in this game climbs, so a sound that falls reads as a threat
    // before the player has worked out what made it.
    if (bossOn && bar % 2 === 0) {
        const f0 = rootHz * 2;
        tone({ at: at0 + beat * 0.5, freq: f0, to: f0 * 0.60, type: "triangle", dur: barSec * 0.7, gain: 0.028, bus });
        tone({ at: at0 + beat * 1.2, freq: f0 * 0.75, to: f0 * 0.48, type: "triangle", dur: barSec * 0.6, gain: 0.022, bus });
    }

    // ── NEARLY DEAD ── a thin high band over everything, scaled off how bad it is. The screen's red wash says
    // this too (see VIGNETTE), and the complaint it exists to prevent is "I did not notice I was low" — which
    // is exactly the sort of thing a player watching their own character catches with their ears first.
    if (danger > 0.72) {
        breath({ at: at0, dur: barSec * 0.8, gain: 0.020 * ((danger - 0.72) / 0.28),
            type: "bandpass", from: 3400, to: 4200, q: 7, bus });
    }
}

function tick() {
    const p = audioParts();
    if (!bed || !p) return;
    const { ctx } = p;
    // Nothing can sound out of a parked context, and bars built against a clock that is not moving would
    // all land on the same instant when it starts. Autoplay policy parks it until a gesture; `armGesture`
    // is what gets it back.
    if (ctx.state !== "running") return;
    // ⚠️ RESYNC RATHER THAN CATCH UP. A hidden tab throttles setInterval to about once a second while the
    // audio clock keeps running, so without this the next tick would build ten bars at once and dump every
    // one of them on the same moment. Same class of bug as the Grove's own pause clock: the fault is in the
    // deadlines, not in the step.
    if (bed.nextAt < ctx.currentTime) bed.nextAt = ctx.currentTime + 0.05;
    while (bed.nextAt < ctx.currentTime + LOOKAHEAD) {
        scheduleBar(bed, bed.bar, bed.nextAt);
        bed.nextAt += bed.spec.barSec;
        bed.bar += 1;
    }
}

function closeBed() {
    if (!bed) return;
    if (bed.timer) clearInterval(bed.timer);
    // The bus, not the timer, is what actually stops it: clearing the timer stops the NEXT bar being
    // scheduled and does nothing about the bar already handed to the audio clock. See subBus/killBus.
    killBus(bed.bus, FADE_OUT);
    bed = null;
}

function openBed(zone) {
    const spec = groveTrack(zone);
    if (!spec) return;
    const p = audioParts();
    if (!p) return;
    unlock();
    const bus = subBus(0.0001);
    if (!bus) return;
    const { ctx } = p;
    try {
        bus.gain.setValueAtTime(0.0001, ctx.currentTime);
        bus.gain.linearRampToValueAtTime(BED_GAIN, ctx.currentTime + FADE_IN);
    } catch { /* fall through on a torn-down context */ }
    bed = { spec, bus, bar: 0, nextAt: ctx.currentTime + 0.12, timer: setInterval(tick, TICK_MS) };
    tick();
}

/**
 * The listeners, attached once and never removed.
 *
 * ⚠️ A HIDDEN TAB IS SILENT. The scene already cancels its own frame loop on visibilitychange; a bed that
 * kept going would be a forest playing out of a tab nobody is looking at, which is the single most annoying
 * thing a web page can do. It comes back where the zone left off — bar zero, because this is ambient and
 * there is no phrase to resume into.
 *
 * ⚠️ AND A GESTURE RESCUES IT. Entering a zone always follows taps, so the context is normally running by the
 * time this starts — but a bed is long-lived in a way a sound effect is not, and the one case that matters
 * (a page restored with the Grove already open) would otherwise be permanently silent with nothing to say so.
 */
function armListeners() {
    if (listening || typeof document === "undefined") return;
    listening = true;
    document.addEventListener("visibilitychange", () => {
        if (document.hidden) closeBed();
        else if (wanted && !bed) openBed(wanted);
    });
    // ⚠️ GUARDED BEFORE IT DOES ANYTHING. These two listeners are on `window` for the life of the page, and
    // the Grove is left long before the tab is — so the common case by far is a tap with no bed wanted at
    // all. It has to cost a boolean then, not an `ensure()` and a resume check on every tap on every screen
    // for the rest of the session.
    const kick = () => {
        if (!wanted || bed) return;
        unlock();
        if (audioParts()) openBed(wanted);
    };
    window.addEventListener("pointerdown", kick, { passive: true });
    window.addEventListener("keydown", kick);
}

/**
 * Play the zone. Idempotent: called with the zone already playing it does nothing, so it is safe in an effect
 * that re-runs — walking through a gate swaps the bed, re-rendering does not.
 */
export function startGroveMusic(zone) {
    const spec = groveTrack(zone);
    if (!spec) return;
    armListeners();
    wanted = zone;
    if (bed?.spec.key === spec.key) return;
    closeBed();
    if (typeof document !== "undefined" && document.hidden) return;
    openBed(zone);
}

/** Leaving the Grove. Fades rather than cuts — a zone should end, not stop. */
export function stopGroveMusic() {
    wanted = null;
    danger = 0;
    bossOn = false;
    closeBed();
}

/** 0 comfortable, 1 about to die. Drives which layers play; read from the scene's own health fraction. */
export function setGroveDanger(v) {
    danger = Math.max(0, Math.min(1, Number(v) || 0));
}

/** Whether something very large has noticed you. Turns the harmony sour and starts the falling pair. */
export function setGroveBoss(on) {
    bossOn = Boolean(on);
}

/**
 * Pull the bed down behind a panel without stopping it.
 *
 * The workbench, the backpack and the map all pause the scene, and a player standing in a menu for two
 * minutes should not be listening to a forest at full level — but killing it would make every panel open and
 * close a fade out and a fade in, which is audible fidgeting. One gain ramp instead.
 */
export function duckGroveMusic(on) {
    const p = audioParts();
    if (!bed?.bus || !p) return;
    const { ctx } = p;
    try {
        const g = bed.bus.gain;
        g.cancelScheduledValues(ctx.currentTime);
        g.setValueAtTime(g.value, ctx.currentTime);
        g.linearRampToValueAtTime(on ? BED_GAIN * 0.3 : BED_GAIN, ctx.currentTime + 0.5);
    } catch { /* ignore */ }
}

/** What is sounding right now, for the lab's readout. Null when nothing is. */
export const groveBedKey = () => bed?.spec.key || null;
